{{ config(materialized='incremental', unique_key='activity_date', incremental_strategy='merge') }}

select
    date_trunc('day', paid_at)::date as activity_date,
    count(distinct seller_id) as active_sellers
from {{ ref('stg_orders') }}
where status = 'paid'
{% if is_incremental() %}
  and paid_at >= (select max(activity_date) - interval '3 days' from {{ this }})
{% endif %}
group by 1
